-- WARNING: replaces all rows in the 13 project tables; make a backup first.

-- Preserves tables, views, procedures, and other triggers.

DROP TRIGGER IF EXISTS `history_before_delete`;

DROP TRIGGER IF EXISTS `prescription_item_before_delete`;

DROP TRIGGER IF EXISTS `gp_before_delete`;

DROP TRIGGER IF EXISTS `specialist_before_delete`;

SET @previous_sql_safe_updates = @@SQL_SAFE_UPDATES;

SET SQL_SAFE_UPDATES = 0;

SET FOREIGN_KEY_CHECKS = 0;

START TRANSACTION;

DELETE FROM `prescription_item`;

DELETE FROM `prescription`;

DELETE FROM `medical_history`;

DELETE FROM `consultation_session`;

DELETE FROM `appointment`;

DELETE FROM `doctor_schedule`;

DELETE FROM `general_practitioner`;

DELETE FROM `specialist`;

DELETE FROM `doctor`;

DELETE FROM `patient`;

DELETE FROM `specialty`;

DELETE FROM `medication`;

DELETE FROM `user_account`;

SET FOREIGN_KEY_CHECKS = 1;














COMMIT;

SET SQL_SAFE_UPDATES = @previous_sql_safe_updates;

DELIMITER $$
CREATE TRIGGER history_before_delete BEFORE DELETE ON medical_history FOR EACH ROW
BEGIN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'CLINIC: Medical history cannot be deleted.';
END$$
DELIMITER ;

DELIMITER $$
CREATE TRIGGER prescription_item_before_delete BEFORE DELETE ON prescription_item FOR EACH ROW
BEGIN
    IF (SELECT COUNT(*) FROM prescription_item WHERE prescription_id = OLD.prescription_id) <= 1 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'CLINIC: A prescription must retain at least one item.';
    END IF;
END$$
DELIMITER ;

DELIMITER $$
CREATE TRIGGER gp_before_delete BEFORE DELETE ON general_practitioner FOR EACH ROW
BEGIN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'CLINIC: Doctor must retain its subtype.'; END$$
DELIMITER ;

DELIMITER $$
CREATE TRIGGER specialist_before_delete BEFORE DELETE ON specialist FOR EACH ROW
BEGIN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'CLINIC: Doctor must retain its subtype.'; END$$
DELIMITER ;

SELECT (SELECT COUNT(*) FROM `user_account`) + (SELECT COUNT(*) FROM `patient`) + (SELECT COUNT(*) FROM `specialty`) + (SELECT COUNT(*) FROM `doctor`) + (SELECT COUNT(*) FROM `general_practitioner`) + (SELECT COUNT(*) FROM `specialist`) + (SELECT COUNT(*) FROM `doctor_schedule`) + (SELECT COUNT(*) FROM `appointment`) + (SELECT COUNT(*) FROM `consultation_session`) + (SELECT COUNT(*) FROM `medical_history`) + (SELECT COUNT(*) FROM `medication`) + (SELECT COUNT(*) FROM `prescription`) + (SELECT COUNT(*) FROM `prescription_item`) AS total_rows;

SELECT `status`, COUNT(*) AS row_count FROM `appointment` GROUP BY `status` ORDER BY `status`;
